input.old_string:
func parse(
    fileURL: URL,
    projectPath: String,
    completion: @escaping (Session?) -> Void
) {
    DispatchQueue.global(qos: .userInitiated).async {
        let session = self.parseSync(fileURL: fileURL, projectPath: projectPath)
        DispatchQueue.main.async {
            completion(session)
        }
    }
}

